 *   the UI says so instead of offering a dead button (R1).
 * @example canRequestUpdate({ commands: { supported: ['requestUpdate'] } }) => true
 ***/
export const canRequestUpdate = (runner = {}) => canRequestCommand(runner, 'requestUpdate');

